    --border-color: #333333;
    --card-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: var(--font-main);
    line-height: 1.6;
    overflow-x: hidden;
}

/* Header Styles */
.main-header {
    background-color: rgba(10, 10, 10, 0.95);
    border-bottom: 1px solid var(--border-color);
    padding: 1rem 5%;
    position: sticky;
    top: 0;
    z-index: 1000;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
    color: var(--text-primary);
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    color: var(--text-secondary);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s ease;
}

.nav-links a:hover {
    color: var(--text-primary);
}

.header-actions button {
    background: none;
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: background 0.3s;
}

.header-actions button:hover {
    background-color: var(--surface-color);
}

/* Hero Section */
.hero {
    height: 80vh;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 0 5%;
}

.hero-content h1 {
    font-size: 4rem;
    margin-bottom: 1rem;
    letter-spacing: -1px;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 2rem;
}

.cta-button {
    background-color: var(--accent-color);
    color: white;
    padding: 1rem 2rem;
    text-decoration: none;
    border-radius: 4px;
    font-weight: 600;
    transition: background 0.3s;
    display: inline-block;
}

.cta-button:hover {
    background-color: var(--accent-hover);
}

/* Product Grid */
.products-section {
    padding: 5rem 5%;
}

.products-section h2 {
    font-size: 2rem;
    margin-bottom: 3rem;
    text-align: center;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 12px;
    padding: 1.5rem;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    border: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    transform: translateY(-5px);
    box-shadow: var(--card-shadow);
}

.product-image {
    width: 100%;
    height: 200px;
    background-color: #2a2a2a;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    object-fit: cover;
}

.product-info h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.product-price {
    font-weight: 700;
    color: var(--accent-color);
    font-size: 1.1rem;
    margin-bottom: 1rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.75rem;
    background-color: transparent;
    border: 1px solid var(--accent-color);
    color: var(--accent-color);
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
    transition: all 0.3s;
    margin-top: auto;
}

.add-to-cart:hover {
    background-color: var(--accent-color);
    color: white;
}

/* Deals Section */
.deals-section {
    background-color: #000;
    padding: 5rem 5%;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
    gap: 2rem;
}

.deal-card {
    background: linear-gradient(135deg, #1a1a1a 0%, #0a0a0a 100%);
    border: 1px solid var(--accent-color);
    border-radius: 12px;
    padding: 2rem;
    position: relative;
    overflow: hidden;
}

.deal-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: #ff1744;
    color: white;
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 700;
}

/* Editorial Secondary */
.editorial-secondary {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1px;
    background-color: var(--border-color);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.editorial-card {
    background-color: var(--bg-color);
    padding: 5rem 10%;
    text-align: center;
}

.editorial-card h3 {
    font-size: 1.75rem;
    margin-bottom: 1.5rem;
}

.editorial-card p {
    color: var(--text-secondary);
}

/* Footer */
.main-footer {
    padding: 5rem 5% 2rem;
    background-color: #050505;
}

.footer-content {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 3rem;
    margin-bottom: 4rem;
}

.footer-links {
    display: flex;
    gap: 2rem;
}

.footer-links a {
    color: var(--text-secondary);
    text-decoration: none;
}

.footer-bottom {
    text-align: center;
    border-top: 1px solid var(--border-color);
    padding-top: 2rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Accessibility & Focus */
button:focus, a:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Mobile Responsive */
@media (max-width: 768px) {
    .hero-content h1 {
        font-size: 2.5rem;
    }
    .editorial-secondary {
        grid-template-columns: 1fr;
    }
    .nav-links {
        display: none;
    }
}
